import json
with open('/root/trace_distill_repair/pipeline_output/phase3_checkpoint.json') as f:
    data = json.load(f)
if isinstance(data, list):
    print(f'Total entries: {len(data)}')
    from collections import Counter
    conds = Counter(item.get('condition', '?') for item in data)
    print(f'By condition: {dict(conds)}')
    if data:
        print(f'Fields: {list(data[0].keys())}')
        for cond_name in ['no_trace', 'full_trace', 'structural_filtered', 'line_filtered']:
            cond_items = [d for d in data if d.get('condition') == cond_name]
            if cond_items:
                judges = [d.get('judge_score', d.get('judge', d.get('llm_judge', None))) for d in cond_items]
                judges = [j for j in judges if j is not None]
                test_pass = [d.get('test_pass', d.get('test_execution', d.get('success', None))) for d in cond_items]
                test_pass = [t for t in test_pass if t is not None]
                tokens_in = [d.get('input_tokens', d.get('tokens_input', d.get('prompt_tokens', None))) for d in cond_items]
                tokens_in = [t for t in tokens_in if t is not None]
                tokens_out = [d.get('output_tokens', d.get('tokens_output', d.get('completion_tokens', None))) for d in cond_items]
                tokens_out = [t for t in tokens_out if t is not None]
                print(f'  {cond_name} ({len(cond_items)} instances):')
                if judges: print(f'    Judge: mean={sum(judges)/len(judges):.2f}, scores={sorted(Counter(judges).items())}')
                if test_pass: print(f'    Test pass: {sum(1 for t in test_pass if t)}/{len(test_pass)} ({sum(1 for t in test_pass if t)/len(test_pass)*100:.1f}%)')
                if tokens_in: print(f'    Input tokens: mean={sum(tokens_in)/len(tokens_in):.0f}, min={min(tokens_in)}, max={max(tokens_in)}')
                if tokens_out: print(f'    Output tokens: mean={sum(tokens_out)/len(tokens_out):.0f}')
elif isinstance(data, dict):
    print(f'Keys: {list(data.keys())[:20]}')
"
